={
  "model": "claude-3-5-sonnet-20241022",
  "max_tokens": 1500,
  "system": "Eres el redactor jefe de marketing editorial para librerías independientes y cuentas de Bookstagram. Transforma la reseña en un carrusel de Instagram de 5 diapositivas (cover_hook, quote, synopsis, highlights, cta) y un caption con hashtags. Responde ÚNICA Y EXCLUSIVAMENTE con un JSON válido sin texto adicional ni markdown: {\"caption\": \"...\", \"hashtags\": [\"#libros\", ...], \"slides\": [{\"type\": \"cover_hook\", \"title\": \"...\", \"subtitle\": \"...\"}, {\"type\": \"quote\", \"quote\": \"...\", \"subtitle\": \"...\"}, {\"type\": \"synopsis\", \"title\": \"...\", \"body\": \"...\"}, {\"type\": \"highlights\", \"title\": \"...\", \"body\": \"...\"}, {\"type\": \"cta\", \"title\": \"...\", \"body\": \"...\"}]}",
  "messages": [
    {
      "role": "user",
      "content": "LIBRO: {{$json.body.bookTitle}}\nAUTOR: {{$json.body.bookAuthor}}\nRESEÑA:\n{{$json.body.reviewText}}"
    }
  ]
}

={
  "book": {
    "title": $('Webhook: Iniciar Generación').item.json.body.bookTitle,
    "author": $('Webhook: Iniciar Generación').item.json.body.bookAuthor,
    "genre": $('Webhook: Iniciar Generación').item.json.body.genre,
    "coverImageUrl": $('Webhook: Iniciar Generación').item.json.body.coverImageUrl
  },
  "bookstore": $('Webhook: Iniciar Generación').item.json.body.bookstore,
  "theme": $('Webhook: Iniciar Generación').item.json.body.theme || 'editorial_classic',
  "aspectRatio": $('Webhook: Iniciar Generación').item.json.body.aspectRatio || '4:5',
  "slides": JSON.parse($json.content[0].text.replace(/```json\n?|```/g, '')).slides
}
